theorem compileProgram_correct {lim : Limits} {P : Program} {p0 : ℕ} {dec : Bool}
    {μ : ℕ → ℤ} {i j : ℤ} {σ' : State} {c : ℕ} {m : ℤ → BitVec W}
    (h : Exec lim P 0 (mainStmt p0) ⟨frame [0, i, j], μ⟩ σ' c)
    (hfit : Fits W lim (dispPos P dec) (stackCells P lim)) (hm : Input lim μ i j m) :
    ∃ m' : ℤ → BitVec W, exec (compileProgram P p0 dec) (ramSteps P dec c) 0 m
        = some (verdictOf dec (σ'.loc 0), m') ∧ Outcome lim P dec m σ' m'

/-- The classes of the statement are those of the proof. -/
def toNc {F : Type u} [CommSemiring F] (f : Family F) : Nc.Family F :=
  { X := f.vars, fin := f.fin, poly := f.poly }

/-- And conversely. -/
def ofNc {F : Type u} [CommSemiring F] (f : Nc.Family F) : Family F :=
  { vars := f.X, fin := f.fin, poly := f.poly }

/-- VP is a proper subset of VNP over every field. -/
theorem separation : Separation.{u} := fun F _ =>
  ⟨fun f hf => ((Paper.cor_allclasses F).1 (hf : toNc f ∈ Nc.VP F) : toNc f ∈ Nc.VNP F),
    fun h => (Paper.cor_allclasses F).2 fun g hg => (h (a := ofNc g) hg : ofNc g ∈ VP F)⟩

/-- `f` is approximated by a circuit with at most `s` gates. -/
def Approximates {F : Type u} {V : Type} [Field F] (f : MvPolynomial V F) (s : ℕ) : Prop :=
  ∃ q : MvPolynomial V (LaurentSeries F), Computes q s ∧
    ∀ (d : V →₀ ℕ) (i : ℤ), i ≤ 0 →
      (MvPolynomial.coeff d q).coeff i = if i = 0 then MvPolynomial.coeff d f else 0

def VPBar (F : Type u) [Field F] : Set (Family F) :=
  {f | ∃ a : ℕ, ∀ n, Fintype.card (f.vars n) ≤ n ^ a + a ∧
    (f.poly n).totalDegree ≤ n ^ a + a ∧ Approximates (f.poly n) (n ^ a + a)}

structure Family (F : Type u) [CommSemiring F] where
  vars : ℕ → Type
  [fin : ∀ n, Fintype (vars n)]
  poly : ∀ n, MvPolynomial (vars n) F

def VP (F : Type u) [CommSemiring F] : Set (Family F) :=
  {f | ∃ a : ℕ, ∀ n, Fintype.card (f.vars n) ≤ n ^ a + a ∧ (f.poly n).totalDegree ≤ n ^ a + a ∧
    Computes (f.poly n) (n ^ a + a)}

def VNP (F : Type u) [CommSemiring F] : Set (Family F) :=
  {f | ∃ (r : ℕ → ℕ) (g : ∀ n, MvPolynomial (f.vars n ⊕ Fin (r n)) F),
    ({ vars := fun n => f.vars n ⊕ Fin (r n), poly := g } : Family F) ∈ VP F ∧
      ∀ n, f.poly n = ∑ e : Fin (r n) → Bool, aeval (Sum.elim X fun i => if e i then 1 else 0) (g n)}

def Separation : Prop := ∀ (F : Type u) [Field F], VP F ⊂ VNP F

def SeparationClosure : Prop := ∀ (F : Type u) [Field F], ¬ VNP F ⊆ VPBar F

theorem Solution.separation : Separation.{u}
theorem Solution.separationClosure : SeparationClosure.{u}
